function _fuseGemGroup(skId){
  // 선택된 파트너가 있다면 해당 그룹을 우선 반환 (중복 그룹 스킬 대응)
  if(_fuseSelId && _fuseSelId !== skId){
    for(const[k,g]of Object.entries(_FUSE_GEM_GROUPS)){
      if(g.skills.includes(skId) && g.skills.includes(_fuseSelId)){
        const slv=P.skills[skId]||1;
        const tier=slv>=10?'gold':slv>=5?'silver':'clear';
        return {key:k,...g,tier};
      }
    }
  }
  // 복수 그룹 소속: 가장 작은(기본 합체) 그룹 우선 → 1단 색 통일
  // 2단 전용 스킬(1단에 없는 스킬)은 2단 그룹 색
  let _bestG=null,_bestK=null,_bestN=9999;
  for(const[k,g]of Object.entries(_FUSE_GEM_GROUPS)){
    if(!g.skills.includes(skId))continue;
    if(g.skills.length<_bestN){_bestN=g.skills.length;_bestG=g;_bestK=k}
  }
  if(_bestG){const slv=P.skills[skId]||1;const tier=slv>=10?'gold':slv>=5?'silver':'clear';return{key:_bestK,..._bestG,tier}}
  return null;
}

