const _synth=P.skills.whirlwind>=1&&P.skills.detonate>=1&&_isFused('whirlDet');
const _isStormBeam=sk.id==='whirlwind'&&_stormBeamF;
const _isSlamStorm=sk.id==='whirlwind'&&_slamStormF&&!_stormBeamF;
const _isSynth=sk.id==='whirlwind'&&_synth&&!_slamStormF&&!_stormBeamF;
const _bladeFuse=P.skills.maliceHunt>=1&&P.skills.guardian>=1&&_isFused('bladeFuse');
const _isBladeFuse=sk.id==='maliceHunt'&&_bladeFuse&&!(P.skills.plagueBurst>=1&&_isFused('plagueFuse'));
const _iceMortarFuse=P.skills.maliceMortar>=1&&P.skills.iceOrb>=1&&_isFused('iceMortar');
const _isIceFuse=sk.id==='maliceMortar'&&_iceMortarFuse;
const _elemFuseF=P.skills.fanShot>=1&&P.skills.omniBeam>=1&&P.skills.elemMissile>=1&&_isFused('elemFuse');
const _sixFuse=P.skills.fanShot>=1&&P.skills.omniBeam>=1&&_isFused('sixFuse');
const _isElemFuse=sk.id==='omniBeam'&&_elemFuseF&&!_stormBeamF;
const _isSixFuse=sk.id==='fanShot'&&_sixFuse&&!_elemFuseF&&!_stormBeamF;
const _elecRepentF=P.skills.maliceStorm>=1&&P.skills.hellRay>=1&&_isFused('elecRepent');
const _boneStormF=P.skills.maliceStorm>=1&&P.skills.boneWall>=1&&_isFused('boneStorm')&&!_elecRepentF;
const _isElecRepent=sk.id==='maliceStorm'&&_elecRepentF;
const _isBoneStorm=sk.id==='maliceStorm'&&_boneStormF&&!_elecRepentF;
const _shieldFuseF=P.skills.maliceSwipe>=1&&P.skills.shieldThrow>=1&&_isFused('shieldFuse');
const _isShieldFuse=sk.id==='maliceSwipe'&&_shieldFuseF;
const _plagueFuseF=P.skills.maliceHunt>=1&&P.skills.plagueBurst>=1&&_isFused('plagueFuse');
const _plagueVenomF=P.skills.maliceHunt>=1&&P.skills.venomBlade>=1&&_isFused('plagueVenom');
const _isPlagueVenom=sk.id==='maliceHunt'&&P.skills.venomBlade>=1&&_isFused('plagueVenom');
const _isPlagueFuse=sk.id==='maliceHunt'&&_plagueFuseF&&!_isPlagueVenom;
const _holyW4F=_isFused('holyWeak4')&&P.skills.holyDome>=1&&P.skills.weakRev>=1;
const _holyW3F=!_holyW4F&&_isFused('holyWeak3')&&P.skills.holyDome>=1&&P.skills.weakPj>=1;
const _holyW2F=!_holyW4F&&!_holyW3F&&_isFused('holyWeak2')&&P.skills.holyDome>=1&&P.skills.weakMag>=1;
const _holyW1F=!_holyW4F&&!_holyW3F&&!_holyW2F&&_isFused('holyWeak1')&&P.skills.holyDome>=1&&P.skills.weakPhys>=1;
const _holyIceF=!_holyW4F&&!_holyW3F&&!_holyW2F&&!_holyW1F&&P.skills.holyDome>=1&&P.skills.holyPrison>=1&&P.skills.iceStorm>=1&&_isFused('holyIce');
const _holyFuseF=!_holyW4F&&!_holyW3F&&!_holyW2F&&!_holyW1F&&!_holyIceF&&(P.skills.holyDome>=1&&P.skills.holyPrison>=1&&_isFused('holyFuse'));
const _isHolyW4=sk.id==='holyDome'&&_holyW4F;
const _isHolyW3=sk.id==='holyDome'&&_holyW3F;
const _isHolyW2=sk.id==='holyDome'&&_holyW2F;
const _isHolyW1=sk.id==='holyDome'&&_holyW1F;
const _isHolyIce=sk.id==='holyDome'&&_holyIceF;
const _isHolyFuse=sk.id==='holyDome'&&_holyFuseF;
const _pillarSlamF=P.skills.giantSlam2>=1&&P.skills.darkPillar>=1&&_isFused('pillarSlam');
const _pillarSpikeF=P.skills.darkPillar>=1&&P.skills.spikeTrap>=1&&_isFused('pillarSpike')&&!_pillarSlamF;
const _isPillarSlam=sk.id==='giantSlam2'&&_pillarSlamF;
const _isPillarSpike=sk.id==='darkPillar'&&_pillarSpikeF;
const _infernoSlamF=P.skills.giantSlam2>=1&&P.skills.fireAura>=1&&_isFused('infernoSlam')&&!_pillarSlamF;
const _isInfernoSlam=sk.id==='giantSlam2'&&_infernoSlamF;
const _siegeGhostF=P.skills.ghostXbowTurret>=1&&P.skills.voidScarecrow>=1&&_isFused('siegeGhost');
const _isSiegeGhost=sk.id==='ghostXbowTurret'&&_siegeGhostF;
const _dualScarecrowF=P.skills.voidScarecrow>=1&&P.skills.explodeScarecrow>=1&&_isFused('dualScarecrow');
const _isDualScarecrow=sk.id==='voidScarecrow'&&_dualScarecrowF;
const _thunderGhostF=P.skills.bladeDash>=1&&P.skills.thunderStake>=1&&_isFused('thunderGhost');
const _isThunderGhost=sk.id==='bladeDash'&&_thunderGhostF;
const _timeStepF=P.skills.timeWarp>=1&&P.skills.ghostWalk>=1&&_isFused('timeStep');
const _isTimeStep=sk.id==='timeWarp'&&_timeStepF;
const _stormBurstF=_stormBeamF&&P.skills.burstLoop>=1&&_isFused('stormBurst');
const _isStormBurst=sk.id==='whirlwind'&&_stormBurstF;
const slv=P.skills[sk.id]||0; // 0=미습득, 1+=습득(강화 횟수)
const learned=slv>=1;
const _reqMet=sk.requires?(P.skills[sk.requires]||0)>=1:true;
const _hasUltLearned=false; // 필살기 전부 습득 가능
const _lvMet=sk.reqLv?P.lv>=sk.reqLv:true;
const canLearn=!learned&&_reqMet&&_lvMet&&P.sp>=sk.spCost&&G.mats>=_malCost(sk.matCost||0);
const _skMaxLv=20;
const _skLvLock=Math.min(20,~~(P.lv/50)+1); // 50렙당 +1 (Lv1=1렙, Lv50=2렙, Lv100=3렙, ... Lv950=20렙)
// 합체 강화 통합: 구성 스킬 upSp/upMat 합산
const _isFuseUp=_isStormBurst||_isStormBeam||_isDimBlast||_isDimRush||_isDimFuse||_isDimSlam||_isDimThunder||_isSlamStorm||_isSynth||_isElemFuse||_isSixFuse||_isBladeFuse||_isIceFuse||_isBoneStorm||_isElecRepent||_isShieldFuse||_isPlagueFuse||_isPlagueVenom||_isHolyFuse||_isHolyIce||_isHolyW1||_isHolyW2||_isHolyW3||_isHolyW4||_isPillarSlam||_isPillarSpike||_isInfernoSlam||_isSiegeGhost||_isDualScarecrow||_isThunderGhost||_isTimeStep;
let _fuseUpSp=0,_fuseUpMat=0,_fuseCanUp=false;
if(_isFuseUp){
  const _fk2=_isStormBurst?'stormBurst':_isStormBeam?'stormBeam':_isDimBlast?'dimBlast':_isDimRush?'dimRush':_isDimThunder?'dimThunder':_isDimSlam?'dimSlam':_isDimFuse?'dimBreach':_isSlamStorm?'slamStorm':_isSynth?'whirlDet':_isElemFuse?'elemFuse':_isSixFuse?'sixFuse':_isBladeFuse?'bladeFuse':_isBoneStorm?'boneStorm':_isElecRepent?'elecRepent':_isShieldFuse?'shieldFuse':_isPlagueVenom?'plagueVenom':_isPlagueFuse?'plagueFuse':_isPillarSlam?'pillarSlam':_isPillarSpike?'pillarSpike':_isInfernoSlam?'infernoSlam':_isSiegeGhost?'siegeGhost':_isDualScarecrow?'dualScarecrow':_isThunderGhost?'thunderGhost':_isTimeStep?'timeStep':_isHolyW4?'holyWeak4':_isHolyW3?'holyWeak3':_isHolyW2?'holyWeak2':_isHolyW1?'holyWeak1':_isHolyIce?'holyIce':_isHolyFuse?'holyFuse':'iceMortar';
  const _fIds2=_fk2==='stormBeam'?['whirlwind','detonate','giantSlam','fanShot','omniBeam','elemMissile']:_fk2==='elemFuse'?['fanShot','omniBeam','elemMissile']:_fk2==='slamStorm'?['whirlwind','detonate','giantSlam']:(_FUSE_PAIRS[_fk2]||[]);
  const _fLv2=Math.min(..._fIds2.map(id=>P.skills[id]||1));
  const _gemGrp=_FUSE_GEM_GROUPS[_fk2];const _gemCnt=(_gemGrp&&_gemGrp.star)||_fIds2.length;_fuseUpSp=_fuseUpSpCost(_fLv2,_gemCnt);
  _fuseCanUp=_fLv2<_skMaxLv&&P.sp>=_fuseUpSp;
}
const _singleUpSp=_skillUpSpCost(slv,false);
const canUp=(learned&&sk.up&&slv<_skMaxLv&&slv<_skLvLock&&P.sp>=_singleUpSp&&G.mats>=_malCost(sk.upMat||0)&&!_isFuseUp)||(_fuseCanUp&&slv<_skLvLock);
const d=document.createElement('div');
d.dataset.skId=sk.id; // 라인 연결용 식별자

