function _skMinusClick(){
    if(!learned)return;
    const _unfuseAllNow=()=>{
      let _refundedSp=0;
      if(P._fused){
        for(const _fk in P._fused){
          if(!P._fused[_fk])continue;
          const _fIds=_FUSE_PAIRS[_fk]||[];
          const _grpDef=_FUSE_GEM_GROUPS&&_FUSE_GEM_GROUPS[_fk];
          if(_fIds.includes(sk.id)||(_grpDef&&_grpDef.skills&&_grpDef.skills.includes(sk.id))){
            delete P._fused[_fk];
            const _avgLv=_fIds.length?Math.min.apply(null,_fIds.map(id=>P.skills[id]||1)):1;
            if(_avgLv>1){
              const _gemC=_fIds.length||1;
              for(let _l=1;_l<_avgLv;_l++){_refundedSp+=_fuseUpSpCost(_l,_gemC)}
            }
          }
        }
      }
      return _refundedSp;
    };
    const _fGrpNow=_fuseGemGroup(sk.id);
    const _isFusedNow=_fGrpNow&&_isFused(_fGrpNow.key);
    const _curLv=(P.skills[sk.id]||0);
    if(_curLv>1){
      // 합체 상태면 합체 단위로 레벨 다운 + 합체 강화비 환불
      const _activeFuseKeys=[];
      for(const _fk of Object.keys(P._fused||{})){
        if(!P._fused[_fk])continue;
        const _fg=_FUSE_GEM_GROUPS[_fk]||{};
        const _ids=(_fg.skills&&_fg.skills.length)?_fg.skills:(_FUSE_PAIRS[_fk]||[]);
        if(_ids.includes(sk.id))_activeFuseKeys.push(_fk);
      }
      if(_activeFuseKeys.length){
        let _bestK=_activeFuseKeys[0],_bestN=0;
        for(const _fk of _activeFuseKeys){
          const _fg=_FUSE_GEM_GROUPS[_fk]||{};
          const _ids=(_fg.skills&&_fg.skills.length)?_fg.skills:(_FUSE_PAIRS[_fk]||[]);
          if(_ids.length>_bestN){_bestN=_ids.length;_bestK=_fk}
        }
        const _bg=_FUSE_GEM_GROUPS[_bestK]||{};
        const _ids=(_bg.skills&&_bg.skills.length)?_bg.skills:(_FUSE_PAIRS[_bestK]||[]);
        const _gemC=(_bg.star)||_ids.length||1;
        const _fLv=Math.min(..._ids.map(id=>P.skills[id]||1));
        if(_fLv>1){
          const _refundSp=_fuseUpSpCost(_fLv-1,_gemC);
          _ids.forEach(id=>{if((P.skills[id]||1)>=_fLv)P.skills[id]=_fLv-1});
          P.sp+=_refundSp;
          SFX.pickup();addTxt(P.x,P.y-30,_T('합체 Lv.')+(_fLv-1)+' (-)','#55ccff',60);
        }else{
          addTxt(P.x,P.y-30,_L('리셋/합체해제는 리셋 버튼 사용','Use Reset button for reset/unfuse'),'#ff6666',60);
          return;
        }
      }else{
        const _refundSp=_skillUpSpCost(_curLv-1,false);
        P.skills[sk.id]=_curLv-1;P.sp+=_refundSp;G.mats+=_malCost(sk.upMat||0);
        SFX.pickup();addTxt(P.x,P.y-30,_T(sk.name)+' Lv.'+(_curLv-1)+' (-)','#ff8844',60);
      }
    }else{
      addTxt(P.x,P.y-30,_L('리셋/합체해제는 리셋 버튼 사용','Use Reset button for reset/unfuse'),'#ff6666',60);
      return;
    }
    renderSkillPanel();updateSkSlot&&updateSkSlot();updateQS&&updateQS();dbSaveForce();
}

